document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("concrete-form"),t=document.getElementById("concrete-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("concrete-length").value),o=parseFloat(document.getElementById("concrete-width").value),r=parseFloat(document.getElementById("concrete-height").value);if(n<=0||o<=0||r<=0)return t.textContent="Please enter all dimensions with positive values.",void 0;const d=n*o*r,c=d/27,s=.0283168*d,i=1.1*c;t.innerHTML=`\n        <div class="result-section">\n          <h4>Concrete Volume Needed:</h4>\n          <p><strong>${c.toFixed(2)} cubic yards</strong></p>\n          <p><strong>${s.toFixed(2)} cubic meters</strong></p>\n          <p>${d.toFixed(1)} cubic feet</p>\n        </div>\n        <div class="result-recommendations">\n          <h4>Ordering Recommendations:</h4>\n          <p><strong>Order: ${i.toFixed(2)} cubic yards</strong> <em>(includes 10% extra)</em></p>\n          <p>🚛 Trucks needed: ${Math.ceil(i/10)} (assuming 10 yd³ trucks)</p>\n        </div>\n        <div class="result-tips">\n          <p><em>💡 Always order 5-10% extra concrete for waste and variations</em></p>\n          <p><em>📞 Call your ready-mix supplier to confirm truck capacity and delivery schedule</em></p>\n        </div>\n      `})});